package ama.api;
import ama.access.*;import ama.meeting.*;import ama.storage.*;import ama.task.*;import ama.transcript.*;import ama.db.TransactionRunner;import ama.minutes.ControlledMinutesDataSource;import ama.contract.IdentityContracts.*;import java.util.*;import java.nio.file.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;import org.springframework.core.env.*;import org.springframework.context.support.StaticApplicationContext;import org.springframework.beans.factory.support.DefaultListableBeanFactory;import com.fasterxml.jackson.databind.ObjectMapper;
/** Pause an actual production member read after S commits; the owner revokes via the normal API. */
public final class LocalReadWithdrawalCheck {
 public static void main(String[] args)throws Exception{
  LocalActionOwnerCheck.check("1".equals(System.getenv("AMA_LOCAL_DEV"))&&args.length==3,"Explicit daily member-read check required");Path file=Path.of(args[0]).toRealPath();LocalActionOwnerCheck.check(file.getParent().endsWith(Path.of(".tools/local-app"))&&Files.size(file)<65536,"Daily configuration required");var p=new Properties();try(var in=Files.newInputStream(file)){p.load(in);}String url=p.getProperty("database.url");LocalActionOwnerCheck.check(url.matches("jdbc:mysql://127\\.0\\.0\\.1:[0-9]+/ama_local_dev\\?.+"),"Owned DB required");String meeting=args[1];UUID.fromString(meeting);Path output=Path.of(args[2]).toRealPath();LocalActionOwnerCheck.check(output.startsWith(file.getParent().resolve("read-withdrawal"))&&!Files.exists(output.resolve("ready.json"))&&!Files.exists(output.resolve("release")),"Fresh qualification coordination directory required");
  var env=new StandardEnvironment();env.getPropertySources().addFirst(new PropertiesPropertySource("daily",p));var source=new LocalActionOwnerCheck.Source(ControlledMinutesDataSource.create(url,p.getProperty("database.user"),p.getProperty("database.password")));var tx=new TransactionRunner(source,30);var fences=new JdbcSubjectFences(source,Set.of("MEETING"));var access=new JdbcMeetingAccess(source,tx,fences);var configured=ConfiguredProcessing.read(env);
  try(var definitions=ConfiguredBackends.read(env);var client=ConfiguredPublication.read(env,configured.read(),configured.index()).client();var context=new StaticApplicationContext()){
   var catalog=new FileBackendCatalog(source,definitions.backends(),definitions.defaultId());catalog.configure();var refs=new HashMap<String,OutboxReferenceValidator>(new MeetingEventReferences(source).validators());refs.putAll(new TranscriptEventReferences(source).validators());refs.putAll(new MinutesEventReferences(source).validators());var outbox=new JdbcOutbox(source,refs);var factory=new ProcessingConfiguration();var processing=factory.processingRuntime(source,tx,access,new TranscriptFilePurposePolicy(),catalog,Map.of(),env);LocalActionOwnerCheck.check(processing.components()!=null,"Genuine processing required");var queue=factory.processingQueue(source,fences,outbox,processing);var transcript=TranscriptConfiguration.assemble(processing,source,fences,outbox,env,context);var beans=new DefaultListableBeanFactory();beans.registerSingleton("qualificationKnowledge",client);var runtime=new MinutesConfiguration().minutesRuntime(processing,transcript,env,queue,outbox,source,beans.getBeanProvider(ControlledKnowledgeClient.class));runtime.requireCombined();
   var actor=new Actor("dev-member",Status.ACTIVE,Set.of(Role.USER));var executor=Executors.newSingleThreadExecutor(r->new Thread(r,"ama-local-action-qualification"));var returned=new AtomicBoolean();source.captured.set(false);source.pauseCapture=true;
   var read=executor.submit(()->{var result=runtime.saved().current(actor,meeting);returned.set(true);return result;});
   try{LocalActionOwnerCheck.check(source.arrived.await(15,TimeUnit.SECONDS),"Actual member S capture COMMIT required");Files.writeString(output.resolve("ready.json"),new ObjectMapper().writeValueAsString(Map.of("phase","AFTER_GENUINE_S_COMMIT","pid",ProcessHandle.current().pid(),"meetingId",meeting)),StandardOpenOption.CREATE_NEW);long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(12);while(!Files.exists(output.resolve("release"))&&System.nanoTime()<deadline)Thread.sleep(30);LocalActionOwnerCheck.check(Files.exists(output.resolve("release")),"Authorized owner API withdrawal must complete before release");source.resume.countDown();
    try{read.get(20,TimeUnit.SECONDS);throw new AssertionError("Revoked member must not receive the captured projection");}catch(ExecutionException failed){LocalActionOwnerCheck.check(failed.getCause() instanceof MeetingAccess.AccessDeniedException,"Actual current meeting ACL denial required at F, found "+failed.getCause().getClass().getSimpleName());}
    LocalActionOwnerCheck.check(!returned.get(),"No captured projection may escape after withdrawal");System.out.println(new ObjectMapper().writeValueAsString(Map.of("pass",true,"meetingId",meeting,"genuineFactories",true,"actualSCaptureCommitted",true,"ownerApiWithdrawalBeforeF",true,"finalCurrentMeetingAclDenied",true,"projectionReturned",false)));
   }finally{source.pauseCapture=false;source.resume.countDown();executor.shutdownNow();executor.awaitTermination(5,TimeUnit.SECONDS);}
  }
 }
}
